//! Exact per-entry maximum element magnitudes for ggml IQ and MXFP4 lookup
//! tables (`ggml-common.h`), used by `quant_scale` for exact realized
//! magnitude bounds and `--clamp-extreme` multipliers.

pub(crate) const KVALUES_IQ4NL: [i8; 16] = [-127, -104, -83, -65, -49, -35, -22, -10, 1, 13, 25, 38, 53, 69, 89, 113];

pub(crate) const KVALUES_MXFP4: [i8; 16] = [0, 1, 2, 3, 4, 6, 8, 12, 0, -1, -2, -3, -4, -6, -8, -12];

/// Maximum `|grid[j] + delta|` for `iq1s_grid[idx]` (`idx < 2048`), where
/// `delta = -0.125` if `neg_delta` else `+0.125`, and every grid entry is in
/// `{-1, 0, +1}`.
#[inline]
pub(crate) fn iq1s_grid_max_abs(idx: usize, neg_delta: bool) -> f64 {
    let mask = (IQ1S_GRID_SIGN_MASK[idx >> 2] >> (2 * (idx & 3))) & 3;
    let has_pos = (mask & 1) != 0;
    let has_neg = (mask & 2) != 0;
    if neg_delta {
        if has_neg {
            1.125
        } else if has_pos {
            0.875
        } else {
            0.125
        }
    } else if has_pos {
        1.125
    } else if has_neg {
        0.875
    } else {
        0.125
    }
}

